// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(address caller, uint64 newNumber) public {
        vm.deal(caller, 1 ether);

        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

        bool ok;
        if (caller == depositor) {
            vm.prank(caller);
            try c.setL1BlockValues(newNumber, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) {
                ok = true;
            } catch {
                ok = false;
            }
            assertTrue(ok && c.number() == newNumber);
        } else {
            vm.prank(caller);
            try c.setL1BlockValues(newNumber, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) {
                ok = true;
            } catch {
                ok = false;
            }

            assertTrue(!ok || c.number() != newNumber);
        }
    }
}
